using Astrea.BattleActions;
using UnityEngine;

namespace Astrea;

[CreateAssetMenu(fileName = "PurifyWithBadEffectCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/PurifyWithBadEffectCustomDescription", order = 0)]
public class PurifyWithBadEffectCustomDescription : CustomBattleActionDescription
{
	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		PurifyWithBadEffectAction purifyWithBadEffectAction = battleAction as PurifyWithBadEffectAction;
		bool isAmountPurify = purifyWithBadEffectAction.IsAmountPurify;
		int amount = (isAmountPurify ? GetAmountWithoutEquation(amountModified) : purifyWithBadEffectAction.PurifyAmount);
		string actionDescription = purifyWithBadEffectAction.PurifyAction.GetActionDescription(amount, GetBonusAmountWithoutEquation(amountModified));
		int amount2 = (isAmountPurify ? purifyWithBadEffectAction.EffectAmount : GetFinalAmountWithoutEquation(amountModified));
		string actionDescription2 = purifyWithBadEffectAction.DefaultEffectAction.GetActionDescription(amount2);
		return actionDescription + "\n" + actionDescription2;
	}
}
